// Layout primitive (Category B) — the responsive page grid. A centered frame with a
// fixed outer margin per tier (Mobile 16 / Tablet 32 / Desktop 48), capped at 1440px
// and centered on desktop, holding a column grid (Mobile 4 / Tablet 8 / Desktop 12;
// gutter 16 / 24 / 24). Children are placed with LayoutGridItem `span`, responsive per
// breakpoint (small → medium 768 → large 1024).
//
// Carve-out 5 (component-contract.md §6): arrangement only, owns no look, no Cmp token
// layer.
//
// `LayoutGridItem` is deliberately UNPROJECTED, and the two §6 rows that settle it are worth
// naming because the absence reads like a gap. Its whole surface is `grid-column: span <n>` plus a
// `min-width: 0` reset: it binds no token, declares no type role, gates no slot and carries no
// `data-*`, which is why all six Figma checks pass over it without a word. §6's Layout row gives an
// arrangement prop NO variant axis, so `span` could not become one; and §6's LayoutGrid row makes
// the parent's `children` SLOT a HORIZONTAL flex row, because Figma refuses a slot on a GRID frame
// — so there are no tracks for an item to span in the first place. A master would be an empty frame
// with a `children` slot, which is what the parent's slot already is. The tier constants (margins, gutters, column counts, 1440 cap) live in the Sys
// grid scale (--sd-grid-*, tokens/sys/grid.json), read directly here; the per-tier swaps
// happen in tokens.css @media blocks (mobile-first min-width:768/1024). The breakpoint
// widths themselves stay literal in those @media conditions (tokens/sys/breakpoint.json is
// their build-time SSOT — @media can't read var()). `--sd-layout-col-span-*` are local
// intermediates, not tokens.
import type { CSSProperties, ElementType, HTMLAttributes, Ref } from "react";
import { responsiveVars, type Responsive } from "./responsive";
import "./LayoutGrid.css";

type Gap =
  | "none"
  | "2x-small"
  | "x-small"
  | "small"
  | "medium"
  | "large"
  | "x-large"
  | "2x-large";

const gapValue = (v: Gap) => (v === "none" ? "0" : `var(--sd-space-${v})`);

export interface LayoutGridProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /**
   * `page` (default): the grid is the page frame and insets its columns by the page-grid margin.
   * `none`: it sits inside a frame that already does (AppShell's main region), so its columns start
   * at the frame's edge instead of one margin further in.
   *
   * @default "page"
   */
  padding?: "page" | "none";
  /**
   * Space between ROWS, from the Sys space scale; the column gutter stays the tier's. Unset, rows
   * are parted by the gutter too. Set it where the items are sections: on a phone they stack into
   * one column, and a gutter equal to a section's own inner gap would erase the grouping, so pass
   * the section-parting rung (two over the loosest gap inside a section, token-contract.md §
   * stacked-units). A responsive value's unset rungs fall back to the next-smaller one.
   */
  rowGap?: Responsive<Gap>;
  /** Render as a different element (e.g. "main", "section"). */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export interface LayoutGridItemProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /**
   * Columns to span, of the current tier's total (Mobile 4 / Tablet 8 / Desktop 12).
   * Responsive per breakpoint; a span wider than the tier clamps to full width.
   */
  span?: Responsive<number>;
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function LayoutGrid({
  padding = "page",
  rowGap,
  as: Component = "div",
  className,
  style,
  ...props
}: LayoutGridProps) {
  return (
    <Component
      {...props}
      data-padding={padding}
      className={className ? `sd-layout-grid ${className}` : "sd-layout-grid"}
      style={{ ...responsiveVars("row-gap", rowGap, gapValue), ...style }}
    />
  );
}

export function LayoutGridItem({
  span,
  as: Component = "div",
  className,
  style,
  ...props
}: LayoutGridItemProps) {
  return (
    <Component
      {...props}
      className={className ? `sd-layout-grid__item ${className}` : "sd-layout-grid__item"}
      style={{ ...responsiveVars("col-span", span, (v) => String(v)), ...style }}
    />
  );
}

/* LayoutGrid.css — .sd-layout-grid (+ __item)
   Responsive page grid. Frame: centered, outer margin + column count + gutter step per
   tier, capped at 90rem (1440px) so the frame centers beyond it. The responsive frame
   values come from the Sys grid scale (--sd-grid-*, tokens/sys/grid.json) — the per-tier
   swaps live in tokens.css @media blocks, so this file just reads the vars (mobile-first:
   base = mobile, min-width:768/1024 widen them). Carve-out 5 (arrangement-only layout
   primitive; grid scale allowlisted in check-token-tiers). The max-width cap never bites
   below 1440px, so it applies at every tier without a breakpoint of its own.
   `rowGap` arrives as --sd-layout-row-gap-* (set inline) and falls back to the gutter, so an
   unset grid parts rows and columns alike.
   --sd-layout-col-span-* and --sd-layout-row-gap-* are local intermediates, not tokens. No
   descendant combinators. */
.sd-layout-grid {
  /* Block inheritance of an ancestor grid's inline row gap. */
  --sd-layout-row-gap-small: initial;
  --sd-layout-row-gap-medium: initial;
  --sd-layout-row-gap-large: initial;
  width: 100%;
  max-width: var(--sd-grid-max-width);
  margin-inline: auto;
  padding-inline: var(--sd-grid-margin);
  display: grid;
  grid-template-columns: repeat(var(--sd-grid-columns), minmax(0, 1fr));
  gap: var(--sd-grid-gutter);
  row-gap: var(--sd-layout-row-gap-small, var(--sd-grid-gutter));
}

.sd-layout-grid[data-padding="none"] {
  padding-inline: 0;
}

.sd-layout-grid__item {
  /* Reset so a nested item doesn't inherit an ancestor's responsive span. */
  --sd-layout-col-span-small: initial;
  --sd-layout-col-span-medium: initial;
  --sd-layout-col-span-large: initial;
  grid-column: span var(--sd-layout-col-span-small, 1);
  min-width: 0;
}

@media (min-width: 768px) {
  .sd-layout-grid {
    row-gap: var(--sd-layout-row-gap-medium, var(--sd-layout-row-gap-small, var(--sd-grid-gutter)));
  }

  .sd-layout-grid__item {
    grid-column: span var(--sd-layout-col-span-medium, var(--sd-layout-col-span-small, 1));
  }
}

@media (min-width: 1024px) {
  .sd-layout-grid {
    row-gap: var(
      --sd-layout-row-gap-large,
      var(--sd-layout-row-gap-medium, var(--sd-layout-row-gap-small, var(--sd-grid-gutter)))
    );
  }

  .sd-layout-grid__item {
    grid-column: span
      var(--sd-layout-col-span-large, var(--sd-layout-col-span-medium, var(--sd-layout-col-span-small, 1)));
  }
}
